<?php $root_id = $section_anchor ?: $section_instance; $title_id = platejka_section_dom_id( $section_instance, 'title' ); $items = is_array( $section_data['items'] ?? null ) ? $section_data['items'] : array(); ?>
<section class="problems" id="<?php echo esc_attr( $root_id ); ?>" aria-labelledby="<?php echo esc_attr( $title_id ); ?>"><div class="container">
  <h2 id="<?php echo esc_attr( $title_id ); ?>"><?php echo esc_html( $section_data['title'] ?? '' ); ?></h2><div class="problems__intro"><?php echo wp_kses_post( $section_data['description'] ?? '' ); ?></div>
  <div class="problems__viewport" data-problems-slider tabindex="0"><div class="problems__track"><?php foreach ( $items as $item ) : ?><article class="problems__card"><div class="problems__card-content"><h3><?php echo esc_html( $item['title'] ?? '' ); ?></h3><div><?php echo wp_kses_post( $item['text'] ?? '' ); ?></div><?php if ( ! empty( $item['value'] ) ) : ?><strong><?php echo esc_html( $item['value'] ); ?></strong><?php endif; ?></div><?php echo platejka_section_image( $item['image'] ?? 0, 'large', array( 'loading' => 'lazy' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped ?></article><?php endforeach; ?></div></div>
</div></section>
